import json, sys, re
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
raw = open(r"C:\Users\30973\AppData\Local\Temp\pi_mem2.json", encoding="utf-8-sig").read()
d = json.loads(raw[raw.index("["):])
txt = json.dumps(d)
for pat in ["MEMORY_SUMMARY", "memory_summary.md", "memories/memory_summary", "read_memory", "search_memory", "list_memor", "codex_memories"]:
    print(pat, "->", txt.count(pat))
# find tools
def tools(o):
    if isinstance(o, dict):
        if "name" in o and "description" in o and isinstance(o.get("name"), str):
            yield o
        for v in o.values(): yield from tools(v)
    elif isinstance(o, list):
        for v in o: yield from tools(v)
names = [t["name"] for t in tools(d)]
print("num tools-ish:", len(names))
print([n for n in names if "memor" in n.lower()])
# print the summary tail
m = re.search(r"MEMORY_SUMMARY", txt)
print(txt[m.start()-200:m.start()+1500] if m else "no MEMORY_SUMMARY")
